def regex_match(pattern: str, text: str) -> bool:
    def parse_seq(s, start):
        i = start
        n = len(s)
        tokens = []
        while i < n:
            c = s[i]
            if c in '|)': break
            if c == '\\':
                i += 1
                atom = ('LIT', s[i])
                i += 1
            elif c == '.':
                atom = ('DOT',)
                i += 1
            elif c == '[':
                i += 1
                chars = set()
                negate = False
                if i < n and s[i] == '^':
                    negate = True
                    i += 1
                while i < n and s[i] != ']':
                    if i + 2 < n and s[i+1] == '-' and s[i+2] != ']':
                        for ch in range(ord(s[i]), ord(s[i+2])+1):
                            chars.add(chr(ch))
                        i += 3
                    else:
                        chars.add(s[i])
                        i += 1
                if i < n: i += 1
                atom = ('CLS', chars, negate)
            elif c == '(':
                i += 1
                sub, i = parse_seq(s, i)
                if i < n and s[i] == ')': i += 1
                atom = ('GRP', sub)
            else:
                atom = ('LIT', c)
                i += 1

            if i < n and s[i] in ('*', '+', '?'):
                q = s[i]
                i += 1
                tokens.append((atom[0], atom[1], q))
            else:
                tokens.append((atom[0], atom[1], None))
        return tokens, i

    def find_split(p):
        depth = 0
        in_bracket = False
        for j in range(len(p)):
            c = p[j]
            if c == '\\' and j + 1 < len(p):
                j += 1
                continue
            if c == '[' and not in_bracket:
                in_bracket = True
                continue
            if c == ']' and in_bracket:
                in_bracket = False
                continue
            if in_bracket:
                continue
            if c == '(': depth += 1
            elif c == ')': depth -= 1
            elif c == '|' and depth == 0:
                return j
        return -1

    def parse(p):
        idx = find_split(p)
        if idx != -1:
            left = parse(p[:idx])
            right = parse(p[idx+1:])
            return [('ALT', left, right)]
        else:
            tokens, _ = parse_seq(p, 0)
            return tokens

    tokens = parse(pattern)
    memo = {}

    def match(ti, j):
        key = (id(tokens), ti, j)
        if key in memo:
            return memo[key]

        if ti == len(tokens):
