                elif t_type == 'DOT':
                    matches_char = True
                elif t_type == 'CLS':
                    chars, negate = t_val
                    matches_char = (c in chars) ^ negate

                if matches_char:
                    if t_q == '?':
                        res = match_next(ti+1, j+1) or match_next(ti+1, j)
                    elif t_q == '+':
                        res = match_next(ti+1, j+1)
                        if not res:
                            k = j + 1
                            while k < len(text):
                                nc = text[k]
