                            k = j
                            while k < len(text):
                                nc = text[k]
                                m = False
                                if t_type == 'LIT': m = (nc == t_val)
                                elif t_type == 'DOT': m = True
                                else: m = (nc in t_val[0]) ^ t_val[1]
                                if not m: break
                                if match_next(ti+1, k+1):
                                    res = True
                                    break
                                k += 1
                    else:
                        res = match_next(ti+1, j+1)

        memo[key] = res
        return res

    def match_next(ti, j):
        return match(ti, j)

    def match_alt(left, right, j):
        key = ('ALT', id(left), id(right), j)
        if key in memo: return memo[key]
        res = match(left, 0, j) or match(right, 0, j)
        memo[key] = res
        return res

    def match_group(sub_tokens, ti, j):
        key = ('GRP', id(sub_tokens), ti, j)
        if key in memo: return memo[key]
        if ti == len(sub_tokens):
            res = (j == len(text))
            memo[key] = res
            return res

        t_type, t_val, t_q = sub_tokens[ti]
