                if matches_char:
                    if t_q == '?':
                        res = match_group(sub_tokens, ti+1, j+1) or match_group(sub_tokens, ti+1, j)
                    elif t_q == '+':
                        res = match_group(sub_tokens, ti+1, j+1)
                        if not res:
                            k = j + 1
                            while k < len(text):
                                nc = text[k]
                                m = False
                                if t_type == 'LIT': m = (nc == t_val)
                                elif t_type == 'DOT': m = True
                                else: m = (nc in t_val[0]) ^ t_val[1]
                                if not m: break
                                if match_group(sub_tokens, ti+1, k+1):
                                    res = True
                                    break
                                k += 1
                    elif t_q == '*':
                        res = match_group(sub_tokens, ti+1, j)
                        if not res:
                            k = j
                            while k < len(text):
                                nc = text[k]
                                m = False
                                if t_type == 'LIT': m = (nc == t_val)
                                elif t_type == 'DOT': m = True
                                else: m = (nc in t_val[0]) ^ t_val[1]
                                if not m: break
                                if match_group(sub_tokens, ti+1, k+1):
                                    res = True
                                    break
                                k += 1
                    else:
                        res = match_group(sub_tokens, ti+1, j+1)

        memo[key] = res
        return res

    return match(0, 0)

def regex_match(pattern: str, text: str) -> bool:
    # Node types:
    # ('LIT', c)
    # ('DOT',)
    # ('CLS', frozenset, negate)
    # ('SEQ', tuple of nodes)
    # ('ALT', left, right)
    # ('STAR', node), ('PLUS', node), ('OPT', node)

    memo = {}
    pos = [0]

    def parse_alt():
        node = parse_seq()
        while pos[0] < len(pattern) and pattern[pos[0]] == '|':
            pos[0] += 1
            right = parse_seq()
            node = ('ALT', node, right)
        return node

    def parse_seq():
        nodes = []
        while pos[0] < len(pattern) and pattern[pos[0]] not in '|)':
            node = parse_quant()
            nodes.append(node)
        if not nodes:
            return ('SEQ', ())
        return ('SEQ', tuple(nodes))

    def parse_quant():
        node = parse_atom()
        if pos[0] < len(pattern) and pattern[pos[0]] in '*+?':
            q = pattern[pos[0]]
            pos[0] += 1
            if q == '*':
                return ('STAR', node)
            elif q == '+':
                return ('PLUS', node)
            elif q == '?':
                return ('OPT', node)
        return node

    def parse_atom():
        if pos[0] >= len(pattern):
            return None
        c = pattern[pos[0]]
        if c == '(':
            pos[0] += 1
            node = parse_alt()
            if pos[0] < len(pattern) and pattern[pos[0]] == ')':
                pos[0] += 1
            return node
        elif c == '[':
            return parse_class()
        elif c == '.':
            pos[0] += 1
            return ('DOT',)
        elif c == '\\':
            if pos[0] + 1 < len(pattern):
                pos[0] += 2
                return ('LIT', pattern[pos[0] - 1])
            else:
                pos[0] += 1
                return ('LIT', '\\')
        else:
            pos[0] += 1
            return ('LIT', c)

    def parse_class():
        pos[0] += 1 # skip '['
        negate = False
        chars = set()
        if pos[0] < len(pattern) and pattern[pos[0]] == '^':
            negate = True
            pos[0] += 1

        while pos[0] < len(pattern) and pattern[pos[0]] != ']':
            if pos[0] + 2 < len(pattern) and pattern[pos[0] + 1] == '-' and pattern[pos[0] + 2] != ']':
                c1 = pattern[pos[0]]
                c2 = pattern[pos[0] + 2]
                start_ord = ord(c1)
                end_ord = ord(c2)
                if start_ord <= end_ord:
                    for code in range(start_ord, end_ord + 1):
                        chars.add(chr(code))
                else:
                    chars.add(c1)
                    chars.add(c2)
                pos[0] += 3
            else:
                chars.add(pattern[pos[0]])
                pos[0] += 1

        if pos[0] < len(pattern):
            pos[0] += 1 # skip ']'
        return ('CLS', frozenset(chars), negate)

    root = parse_alt()
    if pos[0] != len(pattern):
        # Should not happen for well-formed patterns, but just in case
        pass

    def match_set(node, text_idx):
        key = (id(node), text_idx)
        if key in memo:
            return memo[key]

        res = set()

        if node is None:
            res.add(text_idx)
        elif node[0] == 'LIT':
            if text_idx < len(text) and text[text_idx] == node[1]:
                res.add(text_idx + 1)
        elif node[0] == 'DOT':
            if text_idx < len(text):
                res.add(text_idx + 1)
        elif node[0] == 'CLS':
            chars, negate = node[1], node[2]
            if text_idx < len(text):
                c = text[text_idx]
                matches = (c in chars) ^ negate
                if matches:
                    res.add(text_idx + 1)
        elif node[0] == 'SEQ':
            current_indices = {text_idx}
            for sub_node in node[1]:
                next_indices = set()
                for idx in current_indices:
                    next_indices |= match_set(sub_node, idx)
                current_indices = next_indices
                if not current_indices:
                    break
            res = current_indices
        elif node[0] == 'ALT':
            left, right = node[1], node[2]
            res = match_set(left, text_idx) | match_set(right, text_idx)
        elif node[0] == 'STAR':
            current_indices = {text_idx}
            while True:
                next_indices = set()
                for idx in current_indices:
                    next_indices |= match_set(node[1], idx)
                new_states = next_indices - current_indices
                if not new_states:
                    break
                current_indices |= new_states
            res = current_indices
        elif node[0] == 'PLUS':
            current_indices = match_set(node[1], text_idx)
            while True:
                next_indices = set()
                for idx in current_indices:
                    next_indices |= match_set(node[1], idx)
                new_states = next_indices - current_indices
                if not new_states:
                    break
                current_indices |= new_states
            res = current_indices
        elif node[0] == 'OPT':
            res = match_set(node[1], text_idx)
            res.add(text_idx)

        memo[key] = res
        return res

    final_indices = match_set(root, 0)
    return len(text) in final_indices

