class Node: pass
class Literal(Node):
    def __init__(self, char): self.char = char
class Dot(Node): pass
class Bracket(Node):
    def __init__(self, chars, negated): self.chars = chars; self.negated = negated
class Concat(Node):
    def __init__(self, children): self.children = children
class Alternation(Node):
    def __init__(self, children): self.children = children
class Star(Node):
    def __init__(self, child): self.child = child
class Plus(Node):
    def __init__(self, child): self.child = child
class Question(Node):
    def __init__(self, child): self.child = child
class Empty(Node): pass

def regex_match(pattern: str, text: str) -> bool:
    pos = [0]
    def peek(): return pattern[pos[0]] if pos[0] < len(pattern) else None
    def advance(): 
        c = pattern[pos[0]]; pos[0] += 1; return c

    def parse_alternation():
        nodes = [parse_concatenation()]
        while peek() == '|':
            advance()
            nodes.append(parse_concatenation())
        if len(nodes) == 1: return nodes[0]
        return Alternation(nodes)

    def parse_concatenation():
        nodes = []
        while peek() is not None and peek() not in ('|', ')'):
            nodes.append(parse_atom())
        if len(nodes) == 0: return Empty()
        if len(nodes) == 1: return nodes[0]
        return Concat(nodes)

    def parse_atom():
        base = parse_base()
        c = peek()
        if c in ('*', '+', '?'):
            advance()
            if c == '*': return Star(base)
            if c == '+': return Plus(base)
            if c == '?': return Question(base)
        return base

    def parse_base():
        c = peek()
        if c == '(':
            advance()
            node = parse_alternation()
            if peek() == ')': advance()
            return node
        elif c == '[':
            return parse_bracket()
        elif c == '.':
            advance()
            return Dot()
        elif c == '\\':
            advance()
            return Literal(advance())
        else:
            advance()
            return Literal(c)

    def parse_bracket():
        advance() # [
        negated = False
        if peek() == '^':
            negated = True
            advance()
        chars = set()
        while peek() != ']':
            c = advance()
            if peek() == '-' and pos[0] + 1 < len(pattern) and pattern[pos[0]+1] != ']':
                advance() # -
                end = advance()
                for i in range(ord(c), ord(end)+1):
                    chars.add(chr(i))
            else:
                chars.add(c)
        advance() # ]
        return Bracket(chars, negated)

    tree = parse_alternation()

    adj = [] # list of lists of (type, info, to_state)
    # types: 'eps', 'lit', 'dot', 'bracket'
    # info: char for lit, None for dot, (chars, negated) for bracket

    def new_state():
        adj.append([])
        return len(adj) - 1

    def build(node):
        if isinstance(node, Literal):
            s1, s2 = new_state(), new_state()
            adj[s1].append(('lit', node.char, s2))
            return s1, s2
        elif isinstance(node, Dot):
            s1, s2 = new_state(), new_state()
            adj[s1].append(('dot', None, s2))
            return s1, s2
        elif isinstance(node, Bracket):
            s1, s2 = new_state(), new_state()
            adj[s1].append(('bracket', (node.chars, node.negated), s2))
            return s1, s2
        elif isinstance(node, Concat):
            entries = [build(child) for child in node.children]
            for i in range(len(entries)-1):
                adj[entries[i][1]].append(('eps', None, entries[i+1][0]))
            return entries[0][0], entries[-1][1]
        elif isinstance(node, Alternation):
            s1, s2 = new_state(), new_state()
            for child in node.children:
                e, x = build(child)
                adj[s1].append(('eps', None, e))
                adj[x].append(('eps', None, s2))
            return s1, s2
        elif isinstance(node, Star):
            e, x = build(node.child)
            s1, s2 = new_state(), new_state()
            adj[s1].append(('eps', None, e))
            adj[e].append(('eps', None, e))
            adj[x].append(('eps', None, e))
            adj[x].append(('eps', None, s2))
            adj[s1].append(('eps', None, s2))
            return s1, s2
        elif isinstance(node, Plus):
            e, x = build(node.child)
            s1, s2 = new_state(), new_state()
            adj[s1].append(('eps', None, e))
            adj[e].append(('eps', None, e))
            adj[x].append(('eps', None, e))
            adj[x].append(('eps', None, s2))
            return s1, s2
        elif isinstance(node, Question):
            e, x = build(node.child)
            s1, s2 = new_state(), new_state()
            adj[s1].append(('eps', None, e))
            adj[x].append(('eps', None, s2))
            adj[s1].append(('eps', None, s2))
            return s1, s2
        elif isinstance(node, Empty):
            s1, s2 = new_state(), new_state()
            adj[s1].append(('eps', None, s2))
            return s1, s2

    root_entry, root_exit = build(tree)

    eps_closures = [None] * len(adj)
    def compute_eps_closure(s):
        if eps_closures[s] is not None:
            return eps_closures[s]
        stack = [s]
        closure = set()
        while stack:
            u = stack.pop()
            if u in closure: continue
            closure.add(u)
            for typ, info, v in adj[u]:
                if typ == 'eps' and v not in closure:
                    stack.append(v)
        eps_closures[s] = closure
        return closure

    for i in range(len(adj)):
        compute_eps_closure(i)

    current = eps_closures[root_entry]
    for char in text:
        next_states = set()
        for s in current:
            for typ, info, t in adj[s]:
                if typ == 'eps': continue
                if typ == 'lit':
                    if char == info: next_states.add(t)
                elif typ == 'dot':
                    next_states.add(t)
                elif typ == 'bracket':
                    chars, negated = info
                    if negated:
                        if char not in chars: next_states.add(t)
                    else:
                        if char in chars: next_states.add(t)
        current = set()
        for s in next_states:
            current |= eps_closures[s]

    return root_exit in current

def json_parse(s: str):
    if not s or not s.strip():
        raise ValueError("Empty input")
    pos = 0
    n = len(s)

    def skip_ws():
        nonlocal pos
        while pos < n and s[pos] in ' \t\n\r':
            pos += 1

    def parse_value():
        nonlocal pos
        skip_ws()
        if pos >= n:
            raise ValueError("Unexpected end of input")
        c = s[pos]
        if c == '{': return parse_object()
        elif c == '[': return parse_array()
        elif c == '"': return parse_string()
        elif c == 't': return parse_true()
        elif c == 'f': return parse_false()
        elif c == 'n': return parse_null()
        elif c == '-' or c.isdigit(): return parse_number()
        else: raise ValueError(f"Unexpected character: {c}")

    def parse_object():
        nonlocal pos
        pos += 1
        skip_ws()
        if pos < n and s[pos] == '}':
            pos += 1
            return {}
        result = {}
        while True:
            skip_ws()
            if pos >= n or s[pos] != '"':
                raise ValueError("Expected string key in object")
            key = parse_string()
            skip_ws()
            if pos >= n or s[pos] != ':':
                raise ValueError("Expected ':' after object key")
            pos += 1
            skip_ws()
            value = parse_value()
            result[key] = value
            skip_ws()
            if pos < n and s[pos] == ',':
                pos += 1
                continue
            elif pos < n and s[pos] == '}':
                pos += 1
                break
            else:
                raise ValueError("Expected ',' or '}' in object")
        return result

    def parse_array():
        nonlocal pos
        pos += 1
        skip_ws()
        if pos < n and s[pos] == ']':
            pos += 1
            return []
        result = []
        while True:
            skip_ws()
            value = parse_value()
            result.append(value)
            skip_ws()
            if pos < n and s[pos] == ',':
                pos += 1
                continue
            elif pos < n and s[pos] == ']':
                pos += 1
                break
            else:
                raise ValueError("Expected ',' or ']' in array")
        return result

    def parse_string():
        nonlocal pos
        if pos >= n or s[pos] != '"':
            raise ValueError("Expected string")
        pos += 1
        chars = []
        while pos < n:
            c = s[pos]
            if c == '"':
                pos += 1
                return ''.join(chars)
            if c == '\\':
                pos += 1
                if pos >= n:
                    raise ValueError("Unexpected end of string")
                esc = s[pos]
                pos += 1
                if esc == '"': chars.append('"')
                elif esc == '\\': chars.append('\\')
                elif esc == '/': chars.append('/')
                elif esc == 'b': chars.append('\b')
                elif esc == 'f': chars.append('\f')
                elif esc == 'n': chars.append('\n')
                elif esc == 'r': chars.append('\r')
                elif esc == 't': chars.append('\t')
                elif esc == 'u':
                    if pos + 4 > n:
                        raise ValueError("Invalid unicode escape")
                    hex_str = s[pos:pos+4]
                    for h in hex_str:
                        if h not in '0123456789abcdefABCDEF':
                            raise ValueError("Invalid hex in unicode escape")
                    code_point = int(hex_str, 16)
                    pos += 4
                    if 0xD800 <= code_point <= 0xDBFF:
                        if pos + 6 <= n and s[pos] == '\\' and s[pos+1] == 'u':
                            low_hex = s[pos+2:pos+6]
                            for h in low_hex:
                                if h not in '0123456789abcdefABCDEF':
                                    raise ValueError("Invalid hex in unicode escape")
                            low_cp = int(low_hex, 16)
                            if 0xDC00 <= low_cp <= 0xDFFF:
                                combined = 0x10000 + (code_point - 0xD800) * 0x400 + (low_cp - 0xDC00)
                                chars.append(chr(combined))
                                pos += 6
                                continue
                            else:
                                raise ValueError("Expected low surrogate")
                        else:
                            raise ValueError("Expected low surrogate after high surrogate")
                    elif 0xDC00 <= code_point <= 0xDFFF:
                        chars.append(chr(code_point))
                    else:
                        chars.append(chr(code_point))
                else:
                    raise ValueError(f"Invalid escape character: {esc}")
            else:
                if ord(c) < 0x20:
                    raise ValueError("Raw control character in string")
                chars.append(c)
                pos += 1
        raise ValueError("Unterminated string")

    def parse_number():
        nonlocal pos
        start = pos
        if pos < n and s[pos] == '-':
            pos += 1
        if pos >= n or not s[pos].isdigit():
            raise ValueError("Invalid number")
        if s[pos] == '0':
            pos += 1
            if pos < n and s[pos].isdigit():
                raise ValueError("Leading zeros not allowed")
        else:
            while pos < n and s[pos].isdigit():
                pos += 1
        is_float = False
        if pos < n and s[pos] == '.':
            is_float = True
            pos += 1
            if pos >= n or not s[pos].isdigit():
                raise ValueError("Invalid number: expected digit after decimal point")
            while pos < n and s[pos].isdigit():
                pos += 1
        if pos < n and s[pos] in 'eE':
            is_float = True
            pos += 1
            if pos < n and s[pos] in '+-':
                pos += 1
            if pos >= n or not s[pos].isdigit():
                raise ValueError("Invalid number: expected digit after exponent")
            while pos < n and s[pos].isdigit():
                pos += 1
        num_str = s[start:pos]
        if is_float:
            return float(num_str)
        else:
            return int(num_str)

    def parse_true():
        nonlocal pos
        if s[pos:pos+4] == 'true':
            pos += 4
            return True
        raise ValueError("Invalid value")

    def parse_false():
        nonlocal pos
        if s[pos:pos+5] == 'false':
            pos += 5
            return False
        raise ValueError("Invalid value")

    def parse_null():
        nonlocal pos
        if s[pos:pos+4] == 'null':
            pos += 4
            return None
