    result = parse_value()
    skip_ws()
    if pos < n:
        raise ValueError("Trailing non-whitespace")
    return result

def json_parse(s: str):
    if not s or not s.strip():
        raise ValueError("Empty input")
    pos = 0
    n = len(s)

    def skip_ws():
        nonlocal pos
        while pos < n and s[pos] in ' \t\n\r':
            pos += 1

    def parse_value():
        nonlocal pos
        skip_ws()
        if pos >= n:
            raise ValueError("Unexpected end of input")
        c = s[pos]
        if c == '{': return parse_object()
        elif c == '[': return parse_array()
        elif c == '"': return parse_string()
        elif c == 't': return parse_true()
        elif c == 'f': return parse_false()
        elif c == 'n': return parse_null()
        elif c == '-' or c.isdigit(): return parse_number()
        else: raise ValueError(f"Unexpected character: {c}")

    def parse_object():
        nonlocal pos
        pos += 1
        skip_ws()
        if pos < n and s[pos] == '}':
            pos += 1
            return {}
        result = {}
        while True:
            skip_ws()
            if pos >= n or s[pos] != '"':
                raise ValueError("Expected string key in object")
            key = parse_string()
            skip_ws()
            if pos >= n or s[pos] != ':':
                raise ValueError("Expected ':' after object key")
            pos += 1
            skip_ws()
            value = parse_value()
            result[key] = value
            skip_ws()
            if pos < n and s[pos] == ',':
                pos += 1
                continue
            elif pos < n and s[pos] == '}':
                pos += 1
                break
            else:
                raise ValueError("Expected ',' or '}' in object")
        return result

    def parse_array():
        nonlocal pos
        pos += 1
        skip_ws()
        if pos < n and s[pos] == ']':
            pos += 1
            return []
        result = []
        while True:
            skip_ws()
            value = parse_value()
            result.append(value)
            skip_ws()
            if pos < n and s[pos] == ',':
                pos += 1
                continue
            elif pos < n and s[pos] == ']':
                pos += 1
                break
            else:
                raise ValueError("Expected ',' or ']' in array")
        return result

    def parse_string():
        nonlocal pos
        if pos >= n or s[pos] != '"':
            raise ValueError("Expected string")
        pos += 1
        chars = []
        while pos < n:
            c = s[pos]
            if c == '"':
                pos += 1
                return ''.join(chars)
            if c == '\\':
                pos += 1
                if pos >= n:
                    raise ValueError("Unexpected end of string")
                esc = s[pos]
                pos += 1
                if esc == '"': chars.append('"')
                elif esc == '\\': chars.append('\\')
                elif esc == '/': chars.append('/')
                elif esc == 'b': chars.append('\b')
                elif esc == 'f': chars.append('\f')
                elif esc == 'n': chars.append('\n')
                elif esc == 'r': chars.append('\r')
                elif esc == 't': chars.append('\t')
                elif esc == 'u':
                    if pos + 4 > n:
                        raise ValueError("Invalid unicode escape")
                    hex_str = s[pos:pos+4]
                    for h in hex_str:
                        if h not in '0123456789abcdefABCDEF':
                            raise ValueError("Invalid hex in unicode escape")
                    code_point = int(hex_str, 16)
                    pos += 4

                    if 0xD800 <= code_point <= 0xDBFF:
                        # High surrogate
                        # Check for low surrogate
                        is_low_surrogate = False
                        combined_char = None

                        if pos + 6 <= n and s[pos] == '\\' and s[pos+1] == 'u':
                            low_hex = s[pos+2:pos+6]
                            valid_hex = True
                            for h in low_hex:
                                if h not in '0123456789abcdefABCDEF':
                                    valid_hex = False
                                    break
                            if valid_hex:
                                low_cp = int(low_hex, 16)
                                if 0xDC00 <= low_cp <= 0xDFFF:
                                    combined_char = chr(0x10000 + (code_point - 0xD800) * 0x400 + (low_cp - 0xDC00))
                                    is_low_surrogate = True

                        if is_low_surrogate:
                            chars.append(combined_char)
                            pos += 6
                            continue
                        else:
                            chars.append(chr(code_point))
                    elif 0xDC00 <= code_point <= 0xDFFF:
                        # Low surrogate alone
                        chars.append(chr(code_point))
                    else:
                        chars.append(chr(code_point))
                else:
                    raise ValueError(f"Invalid escape character: {esc}")
            else:
                if ord(c) < 0x20:
                    raise ValueError("Raw control character in string")
                chars.append(c)
                pos += 1
        raise ValueError("Unterminated string")

    def parse_number():
        nonlocal pos
        start = pos
        if pos < n and s[pos] == '-':
            pos += 1
        if pos >= n or not s[pos].isdigit():
            raise ValueError("Invalid number")
        if s[pos] == '0':
            pos += 1
            if pos < n and s[pos].isdigit():
                raise ValueError("Leading zeros not allowed")
        else:
            while pos < n and s[pos].isdigit():
                pos += 1
        is_float = False
        if pos < n and s[pos] == '.':
            is_float = True
            pos += 1
            if pos >= n or not s[pos].isdigit():
                raise ValueError("Invalid number: expected digit after decimal point")
            while pos < n and s[pos].isdigit():
                pos += 1
        if pos < n and s[pos] in 'eE':
            is_float = True
            pos += 1
            if pos < n and s[pos] in '+-':
                pos += 1
            if pos >= n or not s[pos].isdigit():
                raise ValueError("Invalid number: expected digit after exponent")
            while pos < n and s[pos].isdigit():
                pos += 1
        num_str = s[start:pos]
        if is_float:
            return float(num_str)
        else:
            return int(num_str)

    def parse_true():
        nonlocal pos
        if s[pos:pos+4] == 'true':
            pos += 4
            return True
        raise ValueError("Invalid value")

    def parse_false():
        nonlocal pos
        if s[pos:pos+5] == 'false':
            pos += 5
            return False
        raise ValueError("Invalid value")

    def parse_null():
        nonlocal pos
        if s[pos:pos+4] == 'null':
            pos += 4
            return None
        raise ValueError("Invalid value")

    result = parse_value()
    skip_ws()
    if pos < n:
        raise ValueError("Trailing non-whitespace")
    return result

