def utf8_decode(b: bytes) -> str:
    res = []
    i = 0
    n = len(b)
    while i < n:
        byte = b[i]

        # Determine expected length and validity of start byte
        # 1-byte sequence
        if 0x00 <= byte <= 0x7F:
            res.append(chr(byte))
            i += 1
            continue

        # 2-byte sequence start
        if 0xC2 <= byte <= 0xDF:
            # Expected 2 bytes total
            # Check if we have at least 1 more byte and it is a valid continuation
            if i + 1 < n and 0x80 <= b[i+1] <= 0xBF:
                # Valid sequence
                code = ((byte & 0x1F) << 6) | (b[i+1] & 0x3F)
                res.append(chr(code))
                i += 2
            else:
                # Truncated or invalid continuation
                # Maximal subpart is just the start byte because the next byte 
                # (if present) is not a valid continuation for this specific sequence type.
                # Even if next byte is 0x80-0xBF, it's valid for 2-byte seq, so we would have taken the if branch.
                # Wait, if next byte is 0x80-0xBF, we take the if branch.
                # So here next byte is NOT 0x80-0xBF or missing.
                # So maximal subpart is length 1.
                res.append('\ufffd')
                i += 1
            continue

        # 3-byte sequence starts
        if byte == 0xE0:
            # Range 0xE0, 2nd byte 0xA0-0xBF, 3rd 0x80-0xBF
            if i + 1 < n and 0xA0 <= b[i+1] <= 0xBF:
                if i + 2 < n and 0x80 <= b[i+2] <= 0xBF:
                    code = ((byte & 0x0F) << 12) | ((b[i+1] & 0x3F) << 6) | (b[i+2] & 0x3F)
                    res.append(chr(code))
                    i += 3
                else:
                    # 2nd byte valid, 3rd missing or invalid
                    # Maximal subpart length 2
                    res.append('\ufffd')
                    i += 2
            else:
                # 2nd byte missing or invalid
                # Maximal subpart length 1
                res.append('\ufffd')
                i += 1
            continue

        if (0xE1 <= byte <= 0xEC) or (0xEE <= byte <= 0xEF):
            # Range 0xE1-0xEC, 0xEE-0xEF. 2nd/3rd bytes 0x80-0xBF
            if i + 1 < n and 0x80 <= b[i+1] <= 0xBF:
                if i + 2 < n and 0x80 <= b[i+2] <= 0xBF:
                    code = ((byte & 0x0F) << 12) | ((b[i+1] & 0x3F) << 6) | (b[i+2] & 0x3F)
                    res.append(chr(code))
                    i += 3
                else:
                    # 2nd byte valid, 3rd missing/invalid
                    res.append('\ufffd')
                    i += 2
            else:
                # 2nd byte missing/invalid
                res.append('\ufffd')
                i += 1
            continue

        if byte == 0xED:
            # Range 0xED. 2nd byte 0x80-0x9F, 3rd 0x80-0xBF
            if i + 1 < n and 0x80 <= b[i+1] <= 0x9F:
                if i + 2 < n and 0x80 <= b[i+2] <= 0xBF:
                    code = ((byte & 0x0F) << 12) | ((b[i+1] & 0x3F) << 6) | (b[i+2] & 0x3F)
                    res.append(chr(code))
                    i += 3
                else:
                    res.append('\ufffd')
                    i += 2
            else:
                res.append('\ufffd')
                i += 1
            continue

        # 4-byte sequence starts
        if byte == 0xF0:
            # Range 0xF0. 2nd 0x90-0xBF, 3rd/4th 0x80-0xBF
            if i + 1 < n and 0x90 <= b[i+1] <= 0xBF:
                if i + 2 < n and 0x80 <= b[i+2] <= 0xBF:
                    if i + 3 < n and 0x80 <= b[i+3] <= 0xBF:
                        code = ((byte & 0x07) << 18) | ((b[i+1] & 0x3F) << 12) | ((b[i+2] & 0x3F) << 6) | (b[i+3] & 0x3F)
                        res.append(chr(code))
                        i += 4
                    else:
                        res.append('\ufffd')
                        i += 3
                else:
                    res.append('\ufffd')
                    i += 2
            else:
                res.append('\ufffd')
                i += 1
            continue

        if 0xF1 <= byte <= 0xF3:
            # Range 0xF1-0xF3. 2nd/3rd/4th 0x80-0xBF
            if i + 1 < n and 0x80 <= b[i+1] <= 0xBF:
                if i + 2 < n and 0x80 <= b[i+2] <= 0xBF:
                    if i + 3 < n and 0x80 <= b[i+3] <= 0xBF:
                        code = ((byte & 0x07) << 18) | ((b[i+1] & 0x3F) << 12) | ((b[i+2] & 0x3F) << 6) | (b[i+3] & 0x3F)
                        res.append(chr(code))
                        i += 4
                    else:
                        res.append('\ufffd')
                        i += 3
                else:
                    res.append('\ufffd')
                    i += 2
            else:
                res.append('\ufffd')
                i += 1
            continue

        if byte == 0xF4:
            # Range 0xF4. 2nd 0x80-0x8F, 3rd/4th 0x80-0xBF
            if i + 1 < n and 0x80 <= b[i+1] <= 0x8F:
                if i + 2 < n and 0x80 <= b[i+2] <= 0xBF:
                    if i + 3 < n and 0x80 <= b[i+3] <= 0xBF:
                        code = ((byte & 0x07) << 18) | ((b[i+1] & 0x3F) << 12) | ((b[i+2] & 0x3F) << 6) | (b[i+3] & 0x3F)
                        res.append(chr(code))
                        i += 4
                    else:
                        res.append('\ufffd')
                        i += 3
                else:
                    res.append('\ufffd')
                    i += 2
            else:
                res.append('\ufffd')
                i += 1
            continue

        # Invalid start bytes (0x80-0xBF, 0xC0-0xC1, 0xF5-0xFF)
        # "single offending byte if no well-formed sequence starts there"
        res.append('\ufffd')
        i += 1

    return ''.join(res)

from datetime import datetime, timedelta
from typing import Optional


def cron_next(expr: str, after: datetime.datetime) -> datetime.datetime | None:
    # Parse the 5 fields
    fields = expr.strip().split()
    if len(fields) != 5:
        raise ValueError("Cron expression must have exactly 5 fields")

    def parse_field(field_str: str, min_v: int, max_v: int, is_dow: bool = False):
        is_restricted = not field_str.startswith('*')
        values: set[int] = set()

        for item in field_str.split(','):
            item = item.strip()
            if not item:
                raise ValueError("Empty item in field")

            step = 1
            if '/' in item:
                parts = item.split('/', 1)
                if len(parts) != 2 or not parts[1].strip():
                    raise ValueError("Invalid step specification")
                base = parts[0].strip()
                try:
                    step = int(parts[1].strip())
                except ValueError:
                    raise ValueError("Step must be a positive integer")
                if step < 1:
                    raise ValueError("Step must be >= 1")
            else:
                base = item

            if base == '*':
                start, end = min_v, max_v
            elif '-' in base:
                r = base.split('-', 1)
                if len(r) != 2:
                    raise ValueError("Invalid range specification")
                try:
                    start, end = int(r[0].strip()), int(r[1].strip())
                except ValueError:
                    raise ValueError("Range values must be integers")
                if start > end:
                    raise ValueError("Start of range cannot be greater than end")
            else:
                try:
                    start = int(base)
                except ValueError:
                    raise ValueError("Invalid value in field")
                end = max_v

            # Validate bounds (allow 0-7 for day-of-week)
            check_max = 7 if is_dow else max_v
            if start < min_v or end > check_max:
                raise ValueError("Value out of range for field")

            if is_dow:
                # Map cron 0-7 (Sun-Sun) to Python weekday 0-6 (Mon-Sun)
                # cron: 0=Sun, 1=Mon, ..., 6=Sat, 7=Sun
                # python: 0=Mon, ..., 5=Sat, 6=Sun
                # formula: (cron - 1) % 7
                for v in range(start, end + 1, step):
                    values.add((v - 1) % 7)
            else:
                for v in range(start, end + 1, step):
                    values.add(v)

        return values, is_restricted

    minute_set, _ = parse_field(fields[0], 0, 59)
    hour_set, _ = parse_field(fields[1], 0, 23)
    dom_set, dom_restricted = parse_field(fields[2], 1, 31)
    month_set, _ = parse_field(fields[3], 1, 12)
    dow_set, dow_restricted = parse_field(fields[4], 0, 6, is_dow=True)

    # Initialize start time: strictly later than `after`, seconds = 0
    dt = after + timedelta(seconds=1)
    dt = dt.replace(second=0, microsecond=0)
    if dt <= after:
        dt += timedelta(minutes=1)

    limit = after + timedelta(days=3000)

    # Iterate minute by minute
    while dt <= limit:
        if dt.minute in minute_set and dt.hour in hour_set and dt.month in month_set:
            # Day matching logic per cron specification
            if dom_restricted and dow_restricted:
                if dt.day in dom_set or dt.weekday() in dow_set:
                    return dt
            else:
                if dt.day in dom_set and dt.weekday() in dow_set:
                    return dt
        dt += timedelta(minutes=1)

    return None

