                    raise ValueError("Start of range cannot be greater than end")
            else:
                try:
                    start = int(base)
                except ValueError:
                    raise ValueError("Invalid value in field")
                end = max_v if step > 1 else start

            # Validate bounds (allow 0-7 for day-of-week)
            check_max = 7 if is_dow else max_v
            if start < min_v or end > check_max:
                raise ValueError("Value out of range for field")

            if is_dow:
                # Map cron 0-7 (Sun-Sun) to Python weekday 0-6 (Mon-Sun)
                for v in range(start, end + 1, step):
                    values.add((v - 1) % 7)
            else:
                for v in range(start, end + 1, step):
                    values.add(v)

        return values, is_restricted

    minute_set, _ = parse_field(fields[0], 0, 59)
    hour_set, _ = parse_field(fields[1], 0, 23)
    dom_set, dom_restricted = parse_field(fields[2], 1, 31)
    month_set, _ = parse_field(fields[3], 1, 12)
    dow_set, dow_restricted = parse_field(fields[4], 0, 6, is_dow=True)

    # Initialize start time: strictly later than `after`, seconds = 0
    dt = after + timedelta(seconds=1)
    dt = dt.replace(second=0, microsecond=0)
    if dt <= after:
        dt += timedelta(minutes=1)

    limit_dt = after + timedelta(days=3000)

    current_date = dt.date()
    limit_date = limit_dt.date()

    sorted_hours = sorted(hour_set)
    sorted_minutes = sorted(minute_set)

    init_hour = dt.hour
    init_minute = dt.minute

    while current_date <= limit_date:
        # Check month
        if current_date.month not in month_set:
            # Skip to next month
            if current_date.month == 12:
                current_date = current_date.replace(year=current_date.year + 1, month=1, day=1)
            else:
                current_date = current_date.replace(month=current_date.month + 1, day=1)
            continue

        is_dom = current_date.day in dom_set
        is_dow = current_date.weekday() in dow_set

        if dom_restricted and dow_restricted:
            if not (is_dom or is_dow):
                current_date += timedelta(days=1)
                continue
        else:
            if not (is_dom and is_dow):
                current_date += timedelta(days=1)
                continue

        # Found a valid day, find earliest time
        start_h = init_hour if current_date == dt.date() else 0
        start_m = init_minute if current_date == dt.date() else 0

        for h in sorted_hours:
            for m in sorted_minutes:
                if h == start_h and m < start_m:
                    continue
                cand = datetime(current_date.year, current_date.month, current_date.day, h, m)
                if cand > limit_dt:
                    return None
                return cand

        current_date += timedelta(days=1)

    return None

