                    raise ValueError("Invalid value in field")
                end = max_v if step > 1 else start

            # Validate bounds (allow 0-7 for day-of-week)
            check_max = 7 if is_dow else max_v
            if start < min_v or end > check_max:
                raise ValueError("Value out of range for field")

            if is_dow:
                # Map cron 0-7 (Sun-Sun) to Python weekday 0-6 (Mon-Sun)
                for v in range(start, end + 1, step):
                    values.add((v - 1) % 7)
            else:
                for v in range(start, end + 1, step):
                    values.add(v)

        return values, is_restricted

    minute_set, _ = parse_field(fields[0], 0, 59)
    hour_set, _ = parse_field(fields[1], 0, 23)
    dom_set, dom_restricted = parse_field(fields[2], 1, 31)
    month_set, _ = parse_field(fields[3], 1, 12)
    dow_set, dow_restricted = parse_field(fields[4], 0, 6, is_dow=True)

    # Initialize start time: strictly later than `after`, seconds = 0
    dt = after + timedelta(seconds=1)
    dt = dt.replace(second=0, microsecond=0)
    if dt <= after:
        dt += timedelta(minutes=1)

    limit_dt = after + timedelta(days=3000)

    current_date = dt.date()
    limit_date = limit_dt.date()

    sorted_hours = sorted(hour_set)
    sorted_minutes = sorted(minute_set)

    init_hour = dt.hour
    init_minute = dt.minute

    while current_date <= limit_date:
        # Check month
        if current_date.month not in month_set:
            # Skip to next month
            if current_date.month == 12:
                current_date = current_date.replace(year=current_date.year + 1, month=1, day=1)
            else:
                current_date = current_date.replace(month=current_date.month + 1, day=1)
            continue

        is_dom = current_date.day in dom_set
        is_dow = current_date.weekday() in dow_set

        if dom_restricted and dow_restricted:
            if not (is_dom or is_dow):
                current_date += timedelta(days=1)
                continue
        else:
            if not (is_dom and is_dow):
                current_date += timedelta(days=1)
                continue

        # Found a valid day, find earliest time
        start_h = init_hour if current_date == dt.date() else 0
        start_m = init_minute if current_date == dt.date() else 0

        for h in sorted_hours:
            for m in sorted_minutes:
                if h == start_h and m < start_m:
                    continue
                cand = datetime(current_date.year, current_date.month, current_date.day, h, m)
                if cand > limit_dt:
                    return None
                return cand

        current_date += timedelta(days=1)

    return None

import datetime

def cron_next(expr: str, after: datetime.datetime) -> datetime.datetime | None:
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("Expected 5 fields")

    def parse_field(field_expr: str, min_val: int, max_val: int) -> list[int]:
        values: set[int] = set()
        for part in field_expr.split(','):
            if not part:
                raise ValueError("Empty part in field")
            step = None
            if '/' in part:
                base, step_s = part.split('/', 1)
                if not step_s.isdigit() or int(step_s) < 1:
                    raise ValueError("Invalid step")
                step = int(step_s)
            else:
                base = part

            if base == '*':
                if step is not None:
                    curr = min_val
                    while curr <= max_val:
                        values.add(curr)
                        curr += step
                else:
                    values.update(range(min_val, max_val + 1))
                continue
            elif '-' in base:
                a_s, b_s = base.split('-', 1)
                if not a_s.isdigit() or not b_s.isdigit():
                    raise ValueError("Invalid range")
                start, end = int(a_s), int(b_s)
                if start > end:
                    raise ValueError("Range start > end")
            elif base.isdigit():
                start = int(base)
                if step is None:
                    end = start
                else:
                    end = max_val
            else:
                raise ValueError("Invalid item")

            if step is not None:
                curr = start
                while curr <= end:
                    if not (min_val <= curr <= max_val):
                        raise ValueError("Out of range")
                    values.add(curr)
                    curr += step
            else:
                if not (min_val <= start <= max_val):
                    raise ValueError("Out of range")
                values.add(start)

        return sorted(values)

    minutes = parse_field(fields[0], 0, 59)
    hours = parse_field(fields[1], 0, 23)
    doms = parse_field(fields[2], 1, 31)
    months = parse_field(fields[3], 1, 12)
    dows = parse_field(fields[4], 0, 7)

    dom_restricted = not fields[2].startswith('*')
    dow_restricted = not fields[4].startswith('*')

    minutes_set = set(minutes)
    hours_set = set(hours)
    doms_set = set(doms)
    months_set = set(months)
    dows_set = {d % 7 for d in dows}  # Normalize 7 to 0 for Sunday

    current = after.replace(second=0, microsecond=0) + datetime.timedelta(seconds=1)
    limit = after + datetime.timedelta(days=3000)

    while current <= limit:
        if current.month not in months_set:
            if current.month == 12:
                current = current.replace(year=current.year + 1, month=1, day=1, hour=0, minute=0)
            else:
                current = current.replace(month=current.month + 1, day=1, hour=0, minute=0)
            continue

        py_dow = current.weekday()
        cron_dow = (py_dow + 1) % 7
        dom_match = current.day in doms_set
        dow_match = cron_dow in dows_set

        if dom_restricted and dow_restricted:
            day_match = dom_match or dow_match
        else:
            day_match = dom_match and dow_match

        if not day_match:
            current = (current + datetime.timedelta(days=1)).replace(hour=0, minute=0)
            continue

        next_hour = None
        for h in hours:
            if h >= current.hour:
                next_hour = h
                break
        if next_hour is not None:
            current = current.replace(hour=next_hour, minute=0)
        else:
            current = (current + datetime.timedelta(days=1)).replace(hour=0, minute=0)
            continue

        next_minute = None
        for m in minutes:
            if m >= current.minute:
                next_minute = m
                break
        if next_minute is not None:
            current = current.replace(minute=next_minute)
        else:
            current = current.replace(minute=0) + datetime.timedelta(hours=1)
            continue

        return current

    return None

