        res = {}
        for d, c in a.items():
            res[d] = res.get(d, 0) + c
        for d, c in b.items():
            res[d] = res.get(d, 0) + c
        return {d: c for d, c in res.items() if c != 0}

    def poly_sub(a, b):
        res = {}
        for d, c in a.items():
            res[d] = res.get(d, 0) + c
        for d, c in b.items():
            res[d] = res.get(d, 0) - c
        return {d: c for d, c in res.items() if c != 0}

    def poly_mul(a, b):
        res = {}
        for d1, c1 in a.items():
            for d2, c2 in b.items():
                res[d1 + d2] = res.get(d1 + d2, 0) + c1 * c2
        return {d: c for d, c in res.items() if c != 0}

    def poly_pow(p, n):
        res = {0: 1}
        for _ in range(n):
            res = poly_mul(res, p)
        return res

    def poly_neg(p):
        return {d: -c for d, c in p.items() if c != 0}

