        poly = parse_term()
        while True:
            tok = peek()
            if tok and tok[1] == '+':
                consume()
                right = parse_term()
                poly = poly_add(poly, right)
            elif tok and tok[1] == '-':
                consume()
                right = parse_term()
                poly = poly_sub(poly, right)
            else:
