        elif tok[1] == '(':
            consume()
            poly = parse_expr()
            consume(')', ')')
            return poly
        else:
            raise ValueError(f"Unexpected token: {tok}")

    result_poly = parse_expr()

    if pos != len(tokens):
        raise ValueError("Unexpected tokens at end of input")

    if not result_poly:
        return "0"

    terms = []
    for d in sorted(result_poly.keys(), reverse=True):
        c = result_poly[d]
        abs_c = abs(c)
        if d == 0:
            var_part = ""
        elif d == 1:
            var_part = "x"
        else:
            var_part = f"x^{d}"

        if abs_c == 1 and d >= 1:
            coeff_part = ""
        else:
            coeff_part = str(abs_c)

