import math

def rational_eval(expr: str) -> str:
    """
    Evaluates an expression exactly over the rationals.

    Grammar:
      expr := term (('+' | '-') term)*
      term := unary (('*' | '/') unary)*
      unary := '-' unary | power
      power := atom ('^' unary)?
      atom := INT | '(' expr ')'

    ^ is right-associative and binds tighter than unary minus.
    Exponent must be an integer.
    Returns "p" or "p/q" in lowest terms.
    """

    class Parser:
        def __init__(self, s: str):
            self.s = s
            self.pos = 0
            self.len = len(s)

        def peek(self):
            if self.pos < self.len:
                return self.s[self.pos]
            return None

        def consume(self, expected=None):
            char = self.peek()
            if expected is not None and char != expected:
                raise ValueError(f"Expected '{expected}', got '{char}' at pos {self.pos}")
            if char is None:
                raise ValueError("Unexpected end of input")
            self.pos += 1
            return char

        def skip_spaces(self):
            while self.pos < self.len and self.s[self.pos] == ' ':
                self.pos += 1

        def parse_expr(self):
            left = self.parse_term()
            while True:
                self.skip_spaces()
                op = self.peek()
                if op in ('+', '-'):
                    self.consume()
                    right = self.parse_term()
                    if op == '+':
                        left = add_rational(left, right)
                    else:
                        left = sub_rational(left, right)
                else:
                    break
            return left

        def parse_term(self):
            left = self.parse_unary()
            while True:
                self.skip_spaces()
                op = self.peek()
                if op in ('*', '/'):
                    self.consume()
                    right = self.parse_unary()
                    if op == '*':
                        left = mul_rational(left, right)
                    else:
                        left = div_rational(left, right)
                else:
                    break
            return left

        def parse_unary(self):
            self.skip_spaces()
            if self.peek() == '-':
                self.consume()
                val = self.parse_unary()
                return neg_rational(val)
            else:
                return self.parse_power()

        def parse_power(self):
            base = self.parse_atom()
            self.skip_spaces()
            if self.peek() == '^':
                self.consume()
                exp = self.parse_unary()
                return pow_rational(base, exp)
            return base

        def parse_atom(self):
            self.skip_spaces()
            char = self.peek()
            if char is None:
                raise ValueError("Unexpected end of input")

            if char == '(':
                self.consume()
                val = self.parse_expr()
                self.skip_spaces()
                if self.peek() != ')':
                    raise ValueError("Expected ')'")
                self.consume()
                return val
            elif char.isdigit():
                start = self.pos
                while self.pos < self.len and self.s[self.pos].isdigit():
                    self.pos += 1
                num_str = self.s[start:self.pos]
                return (int(num_str), 1)
            else:
                raise ValueError(f"Unexpected character '{char}'")

    # Rational arithmetic helpers
    # Representation: (numerator, denominator)
    # Invariant: denominator > 0, gcd(|numerator|, denominator) == 1

    def gcd(a, b):
        return math.gcd(a, b)

    def normalize(n, d):
        if d == 0:
            raise ZeroDivisionError("Division by zero")
        if d < 0:
            n = -n
            d = -d
        common = gcd(abs(n), d)
        return (n // common, d // common)

    def add_rational(a, b):
        n1, d1 = a
        n2, d2 = b
        return normalize(n1 * d2 + n2 * d1, d1 * d2)

    def sub_rational(a, b):
        n1, d1 = a
        n2, d2 = b
        return normalize(n1 * d2 - n2 * d1, d1 * d2)

    def mul_rational(a, b):
        n1, d1 = a
        n2, d2 = b
        return normalize(n1 * n2, d1 * d2)

    def div_rational(a, b):
        n1, d1 = a
        n2, d2 = b
        if n2 == 0:
            raise ZeroDivisionError("Division by zero")
        return normalize(n1 * d2, d1 * n2)

    def neg_rational(a):
        n, d = a
        return normalize(-n, d)

    def pow_rational(base, exp):
        n, d = base
        en, ed = exp

        # Exponent must be an integer
        if ed != 1:
            raise ValueError("Exponent must be an integer")

        k = en

        # 0^0 = 1
        if n == 0 and k == 0:
            return (1, 1)

        # 0 to a negative power is undefined
        if n == 0 and k < 0:
            raise ZeroDivisionError("0 to a negative power")

        # 0 to a positive power is 0
        if n == 0:
            return (0, 1)

        if k >= 0:
            res_n = n ** k
            res_d = d ** k
            return normalize(res_n, res_d)
        else:
            # k < 0
            # (n/d)^k = (d/n)^(-k)
            pos_k = -k
            res_n = d ** pos_k
            res_d = n ** pos_k
            return normalize(res_n, res_d)

    # Main execution
    parser = Parser(expr)
    result = parser.parse_expr()

    # Check for trailing characters
    parser.skip_spaces()
    if parser.pos < parser.len:
        raise ValueError("Unexpected characters at end of input")

    n, d = result
    if d == 1:
        return str(n)
    else:
        return f"{n}/{d}"

def min_window_subseq(s: str, t: str) -> str:
    n, m = len(s), len(t)
    if m == 0:
        return ""

    min_len = n + 1
    best_start = -1

    for i in range(n):
        # If remaining substring is shorter than t, no window can contain t
        if n - i < m:
            break
        # Found the absolute minimum possible length, cannot improve
        if min_len == m:
            break
        # Must start with the first character of t
        if s[i] != t[0]:
            continue

        curr = i
        k = 0
        # Greedily match the rest of t
        while k < m and curr < n:
            if s[curr] == t[k]:
                k += 1
            curr += 1

        if k == m:
            length = curr - i
            if length < min_len:
                min_len = length
                best_start = i

    return s[best_start:best_start + min_len] if best_start != -1 else ""

