                self.consume('<->')
                right = self.parse_implies()
                left = ('<->', left, right)
            return left

        def parse_implies(self):
            left = self.parse_or()
            if self.peek() == '->':
                self.consume('->')
                right = self.parse_implies()
                return ('->', left, right)
            return left

        def parse_or(self):
            left = self.parse_and()
            while self.peek() == '|':
                self.consume('|')
                right = self.parse_and()
                left = ('|', left, right)
            return left

        def parse_and(self):
            left = self.parse_not()
            while self.peek() == '&':
                self.consume('&')
                right = self.parse_not()
                left = ('&', left, right)
            return left

        def parse_not(self):
            if self.peek() == '!':
                self.consume('!')
                operand = self.parse_not()
                return ('!', operand)
            return self.parse_atom()

        def parse_atom(self):
            tok = self.peek()
            if tok == '(':
                self.consume('(')
                expr = self.parse_formula()
                self.consume(')')
                return expr
