    all_vars = sorted(vars_a | vars_b)
    var_to_idx = {v: i for i, v in enumerate(all_vars)}
    n = len(all_vars)

    if n == 0:
        return evaluate(tree_a, (), var_to_idx) == evaluate(tree_b, (), var_to_idx)

    from itertools import product
